import logging
import time
import os
from taf.internal.sbts.admin.exceptions import AdminApiProcedureFailureException
from taf.rfrl.bts.devices.du.logs_collecting.btslog_collector import GnbBtslogCollector, EnbBtslogCollector
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GenericLog, GnbLog, EnbLog
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.robot.decorators import log_as_robot_keyword
from taf.collectors.core.entities.executor import ExecutionError



class GenericLogger(GenericLog):
    def __init__(self, bts_type, bts_log_col, bts_log, bts_id=0, du_id=0, log_dir=None):
        self.bts_type = bts_type
        self.bts_log_col = bts_log_col
        self.bts_log = bts_log
        self.bts_id = bts_id
        self.du_id = du_id
        self.log_dir = log_dir if log_dir is not None else get_builtin_value('OUTPUT DIR')
        os.makedirs(self.log_dir, exist_ok=True)

        super(GenericLogger, self).__init__(bts_type=bts_type)

    @log_as_robot_keyword
    def start_collecting_bts_log(self):
        """    Function is starting collecting BTS log.    """
        log_info_to_console('Start collecting BTS log')
        self.bts_log_col.setup_btslog_collector(bts_id=self.bts_id, du_id=self.du_id)
        self.bts_log_col.start_collecting_btslog(bts_id=self.bts_id, du_id=self.du_id)

    @log_as_robot_keyword
    def stop_collecting_bts_log_and_get_it(self, bts_log_file_prefix='on_air_tl_prep'):
        """    Function is teardowning and downloading BTS log. Printing information about logs location.
        :param str bts_log_file_prefix: prefix added before log name,
        :return: None.
        """
        log_info_to_console('Stop collecting BTS log')
        try:
            self.bts_log_col.stop_collecting_btslog(bts_id=self.bts_id, du_id=self.du_id,
                                                    log_dir=self.log_dir, file_prefix=bts_log_file_prefix)
            self.bts_log_col.teardown_btslog_collector(bts_id=self.bts_id, du_id=self.du_id)
            log_info_to_console('BTS log collected in location: {}'.format(self.log_dir))
        except ExecutionError as e:
            logging.warning("Cannot collect BTS log: {}".format(repr(e)))

    @log_as_robot_keyword
    def collect_snapshots(self, max_tries=5):
        """    Function is downloading Snapshot and Info Model Snapshot . Printing information about logs location.
        :param int max_tries: maximum tries for collecting snapshot, default 5
        :return: None.
        """
        log_info_to_console('Collecting Snapshot and Info Model Snapshot')
        attempt = 1
        while attempt <= max_tries:
            logging.debug("Collect snapshot attempt number: {}".format(attempt))
            try:
                self.bts_log.collect_snapshot(bts_id=self.bts_id, du_id=self.du_id, log_dir=self.log_dir)
                break
            except AdminApiProcedureFailureException as e:
                if 'Snapshot cannot be started when technical report procedure is active' in repr(e):
                    if attempt < max_tries:
                        logging.warning("Caught error during collecting snapshot: {}".format(repr(e)))
                        logging.debug("Sleep 60 sec and try again")
                        time.sleep(60)
                        attempt = attempt + 1
                        continue

                raise e

        self.bts_log.collect_im_snapshot(bts_id=self.bts_id, du_id=self.du_id, log_dir=self.log_dir)
        log_info_to_console('Snapshots collected in location: {}'.format(self.log_dir))


class GnbLogger(GenericLogger):
    bts_type = 'GNB'

    def __init__(self, du_id=0, bts_id=0, log_dir=None):
        super(GnbLogger, self).__init__(bts_type=GnbLogger.bts_type,
                                        bts_log_col=GnbBtslogCollector(),
                                        bts_log=GnbLog(),
                                        du_id=du_id,
                                        bts_id=bts_id,
                                        log_dir=log_dir)


class EnbLogger(GenericLogger):
    bts_type = 'ENB'

    def __init__(self, du_id=0, bts_id=0, log_dir=None):
        super(EnbLogger, self).__init__(bts_type=EnbLogger.bts_type,
                                        bts_log_col=EnbBtslogCollector(),
                                        bts_log=EnbLog(),
                                        du_id=du_id,
                                        bts_id=bts_id,
                                        log_dir=log_dir)
